export const ATP_STD_LIB_WASM_BASE64 =
  "";

let cachedWasmBytes: Uint8Array | undefined;

/**
 * Decodes the pre-bundled `@modelscript/atp-std-lib` `runtime.wasm` binary in Node.js, Browsers, or Web Workers.
 */
export function getAtpStdLibWasmBytes(): Uint8Array {
  if (!cachedWasmBytes) {
    cachedWasmBytes = decodeBase64Wasm(ATP_STD_LIB_WASM_BASE64);
  }
  return cachedWasmBytes;
}
